import json
from pathlib import Path

scenarios = []
EMPTY = dict(source=None, waitingSince=None, waitingSinceEvidence=None, unresolvedDateText=None)
def item(kind, *anchors, source=None, since=None, evidence=None, dates=None, links=None, ambiguity=False):
    sources = source if isinstance(source, list) else [source]
    dates = dates if isinstance(dates, list) else [dates]
    return dict(kinds=kind.split('|'), propertySets=[dict(source=s, waitingSince=since, waitingSinceEvidence=evidence,
        unresolvedDateText=d) for s in sources for d in dates], projectIdSets=links or [[]],
        requireAmbiguity=ambiguity, contentAnchorGroups=[a if isinstance(a, list) else [a] for a in anchors])
def add(id, tags, text, items, canonical, reason=None, projects=(), truncated=False, variants=(), link_review=None):
    reason = reason or 'Сохранить самостоятельные намерения без добавления шагов и дублирования.'
    kinds = ', '.join('/'.join(i['kinds']) for i in items)
    scenarios.append(dict(id=id, tags=tags.split(), text=text, capturedAt='2026-10-25T12:00:00Z',
        context=dict(timeZoneId=None, projects=[dict(id=p[0], title=p[1], createdAt='2026-01-01T00:00:00Z') for p in projects], projectsTruncated=truncated),
        variants=[dict(reason=reason, items=items)] + list(variants), reviewCriteria=dict(
            classification=f'Допустимые типы основного варианта: {kinds}. Проверить намерение, факт, ожидание и обязательство по исходнику; альтернативы описаны в variants.',
            splitting=reason,
            properties='Источник и даты должны соответствовать своим смысловым ролям и этому элементу. Null означает отсутствие доказанного свойства; никакие сроки, участники и действия не выдуманы. Допустимые точные excerpt-варианты в propertySets.',
            links=link_review or 'Без достаточной связи не добавлять projectIds. Проверить контекст, альтернативы и ProjectsTruncated; Project не имеет родителя.',
            canonicalization=canonical)))
A=lambda *a, **kw:item('Action', *a, **kw)
P=lambda *a, **kw:item('Project', *a, **kw)
W=lambda *a, **kw:item('WaitingFor', *a, **kw)
R=lambda *a, **kw:item('Reference', *a, **kw)
S=lambda *a, **kw:item('SomedayMaybe', *a, **kw)

